// Regenerates the committed files that are derived from canonical sources in
// the repository's root folders, or with --check fails when any has drifted.
//
//   npm run sync         rewrite the generated files after changing a source
//   npm run check:sync   verify only (npm run check and CI)
//
// The run-schema and runtime-zip steps run Python; set PYTHON to choose the
// interpreter (default: `python` on Windows, `python3` elsewhere).
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  copyFileSync,
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { inflateRawSync } from "node:zlib";

const repo = fileURLToPath(new URL("../../", import.meta.url));
const check = process.argv.includes("--check");
const python =
  process.env.PYTHON || (process.platform === "win32" ? "python" : "python3");

// Byte-for-byte copies that the app imports or serves for download.
const COPIES = [
  ["templates/catalog.json", "site-app/lib/catalog.json"],
  ["templates/annex-iv-map.json", "site-app/lib/annex-iv-map.json"],
  ["docs/obligation-subitems.json", "site-app/lib/obligation-subitems.json"],
  ["engine/assurance.py", "site-app/public/tools/assurance-verifier.py"],
  ["schemas/threshold-library.json", "site-app/lib/threshold-library.json"],
];
const RUNTIME_ZIP = "site-app/public/tools/assurance-runtime.zip";

const absolute = (file) => path.join(repo, file);
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");
const drift = [];

function runPython(args) {
  const result = spawnSync(python, ["-B", ...args], {
    cwd: repo,
    encoding: "utf8",
  });
  if (result.error)
    throw new Error(
      `Cannot run ${python} (${result.error.message}); set PYTHON to a Python 3.11+ interpreter.`,
    );
  return result;
}

// Lists a zip archive's entries from its central directory. Python's zipfile
// writes neither zip64 records nor archive comments for this package.
function zipEntries(archive) {
  const end = archive.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  if (end < 0) throw new Error("Not a zip archive");
  const entries = new Map();
  let offset = archive.readUInt32LE(end + 16);
  for (let left = archive.readUInt16LE(end + 10); left > 0; left--) {
    if (archive.readUInt32LE(offset) !== 0x02014b50)
      throw new Error("Corrupt zip central directory");
    const method = archive.readUInt16LE(offset + 10);
    const size = archive.readUInt32LE(offset + 20);
    const nameLength = archive.readUInt16LE(offset + 28);
    const extraLength = archive.readUInt16LE(offset + 30);
    const commentLength = archive.readUInt16LE(offset + 32);
    const local = archive.readUInt32LE(offset + 42);
    const name = archive.toString(
      "utf8",
      offset + 46,
      offset + 46 + nameLength,
    );
    const start =
      local +
      30 +
      archive.readUInt16LE(local + 26) +
      archive.readUInt16LE(local + 28);
    const stored = archive.subarray(start, start + size);
    const data = method === 8 ? inflateRawSync(stored) : stored;
    entries.set(name, {
      // Method, modification time and date, external attributes and content.
      key: [
        method,
        archive.readUInt32LE(offset + 12),
        archive.readUInt32LE(offset + 38),
        sha256(data),
      ].join(":"),
      crlf: data.includes("\r\n"),
    });
    offset += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

// The files Git tracks under the given folders, or undefined outside a Git
// checkout (for example an extracted source archive).
function trackedFiles(folders) {
  const result = spawnSync("git", ["ls-files", "-z", "--", ...folders], {
    cwd: repo,
    encoding: "utf8",
  });
  if (result.error || result.status !== 0) {
    console.log("Not a Git checkout; skipping the untracked-file check.");
    return undefined;
  }
  return new Set(result.stdout.split("\0").filter(Boolean));
}

function changedEntries(before, after) {
  const names = [...new Set([...before.keys(), ...after.keys()])].sort();
  return names.flatMap((name) => {
    if (!before.has(name)) return [`+${name}`];
    if (!after.has(name)) return [`-${name}`];
    return before.get(name).key === after.get(name).key ? [] : [name];
  });
}

// 1. The run schema is regenerated by its own generator scripts.
const schema = runPython([
  "schemas/.build-run-schema.py",
  ...(check ? ["--check"] : []),
]);
if (schema.status !== 0)
  drift.push(`schemas/test-run.schema.json: ${schema.stderr.trim()}`);
else console.log(schema.stdout.trim());

// 2. Plain copies.
for (const [source, target] of COPIES) {
  const bytes = readFileSync(absolute(source));
  if (
    existsSync(absolute(target)) &&
    readFileSync(absolute(target)).equals(bytes)
  )
    continue;
  if (check) drift.push(`${target} differs from ${source}`);
  else {
    copyFileSync(absolute(source), absolute(target));
    console.log(`Updated ${target} from ${source}`);
  }
}

// 3. The runtime zip is rebuilt from engine/ and schemas/ in a temporary
// directory. Equal SHA-256 means up to date. Otherwise the entries decide, so a
// different zlib build (for example zlib-ng) does not count as drift.
const temporary = mkdtempSync(path.join(tmpdir(), "assurance-runtime-"));
try {
  const fresh = path.join(temporary, "assurance-runtime.zip");
  const built = runPython(["-m", "engine.package_runtime", "--output", fresh]);
  if (built.status !== 0)
    throw new Error(`engine.package_runtime failed:\n${built.stderr}`);
  const freshBytes = readFileSync(fresh);
  const freshEntries = zipEntries(freshBytes);
  const crlf = [...freshEntries].filter(([, entry]) => entry.crlf);
  // The package must not ship engine tests, their fixtures or generators.
  const tests = [...freshEntries.keys()].filter((name) =>
    name.startsWith("engine/tests/"),
  );
  // package_runtime walks the working tree, so name any packaged file that Git
  // does not track (a scratch note, a pytest cache) instead of shipping it.
  const untracked = trackedFiles(["engine", "schemas"]);
  const stray = untracked
    ? [...freshEntries.keys()].filter(
        (name) => name !== "RUNTIME-MANIFEST.json" && !untracked.has(name),
      )
    : [];
  const committed = existsSync(absolute(RUNTIME_ZIP))
    ? readFileSync(absolute(RUNTIME_ZIP))
    : undefined;
  const identical = committed !== undefined && committed.equals(freshBytes);
  const changed = identical
    ? []
    : committed
      ? changedEntries(zipEntries(committed), freshEntries)
      : ["missing"];
  if (tests.length)
    drift.push(
      `${RUNTIME_ZIP}: engine.package_runtime packaged test files (${tests.join(", ")}); engine/tests/** must stay out of the runtime package.`,
    );
  else if (stray.length)
    drift.push(
      `${RUNTIME_ZIP}: files that Git does not track would be packaged (${stray.join(", ")}); commit or remove them, then run \`npm run sync\`.`,
    );
  else if (crlf.length)
    drift.push(
      `${RUNTIME_ZIP}: the checkout has CRLF line endings in ${crlf.map(([name]) => name).join(", ")}; ` +
        "build the archive from an LF checkout (see .gitattributes).",
    );
  else if (!changed.length)
    console.log(
      identical
        ? `${RUNTIME_ZIP} matches a fresh build (SHA-256 ${sha256(freshBytes)})`
        : `${RUNTIME_ZIP} has the same entries as a fresh build; only the deflate stream differs`,
    );
  else if (check)
    drift.push(
      `${RUNTIME_ZIP} is stale (${changed.join(", ")}); a fresh build has SHA-256 ${sha256(freshBytes)}`,
    );
  else {
    copyFileSync(fresh, absolute(RUNTIME_ZIP));
    console.log(`Updated ${RUNTIME_ZIP} (${changed.join(", ")})`);
  }
} finally {
  rmSync(temporary, { recursive: true, force: true });
}

if (drift.length) {
  console.error(
    `${drift.length} generated file(s) out of date:\n` +
      drift.map((line) => `  - ${line}`).join("\n") +
      "\nRun `npm run sync` in site-app/ and commit the result.",
  );
  process.exit(1);
}
console.log(
  check
    ? "All generated files match their canonical sources."
    : "Generated files are up to date.",
);
